// Companion: stylized adult-proportioned anime character, deliberately seen at eye level.
const avatar=new THREE.Group();avatar.position.set(.35,0,-1.45);scene.add(avatar);
const skinGirl=new THREE.MeshStandardMaterial({color:'#f5d2c7',roughness:.72}), hairGirl=new THREE.MeshStandardMaterial({color:'#18284c',roughness:.83}), hairBlue=new THREE.MeshStandardMaterial({color:'#263d72',roughness:.76}), shirtGirl=new THREE.MeshStandardMaterial({color:'#b9465d',roughness:.88}), skirtGirl=new THREE.MeshStandardMaterial({color:'#334d95',roughness:.84}), glove=new THREE.MeshStandardMaterial({color:'#31538f',roughness:.75}), sock=new THREE.MeshStandardMaterial({color:'#c84a5b',roughness:.84}), hoodie=new THREE.MeshStandardMaterial({color:'#9699a4',roughness:.94}), pants=new THREE.MeshStandardMaterial({color:'#42526d',roughness:.9}), shoe=new THREE.MeshStandardMaterial({color:'#f1e7e5',roughness:.8});
const girl=new THREE.Group(), boy=new THREE.Group();avatar.add(girl,boy);
function limb(parent,a,b,r1,r2,mat){const d=new THREE.Vector3().subVectors(new THREE.Vector3(...b),new THREE.Vector3(...a));let m=new THREE.Mesh(new THREE.CylinderGeometry(r2,r1,d.length(),12),mat);m.position.copy(new THREE.Vector3(...a).add(new THREE.Vector3(...b)).multiplyScalar(.5));m.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),d.normalize());m.castShadow=true;parent.add(m);return m}
function makeHead(g,skin,hair,cap=false){
 // torso proportions: about 7.5 heads tall
 cyl(g,0,1.08,0,.235,.29,.58,shirtGirl); // clothes replaced for male below
 sphere(g,0,1.42,0,.22,.11,.17,skin);
 sphere(g,0,1.77,0,.295,.355,.27,skin);
 // hair cap and shoulder length silhouette
 sphere(g,0,1.9,-.055,.31,.31,.28,hair);sphere(g,-.275,1.69,-.015,.09,.26,.23,hair);sphere(g,.275,1.69,-.015,.09,.26,.23,hair);
 // bangs, swept locks
 for(let i=0;i<5;i++){let x=-.22+i*.11;let lock=sphere(g,x,2.025+Math.sin(i*1.1)*.025,.205,.07,.17,.075,hair);lock.rotation.z=(i-2)*-.15}
 // eye whites and irises on forward-facing z side
 for(let x of [-.115,.115]){sphere(g,x,1.78,.246,.071,.095,.035,new THREE.MeshStandardMaterial({color:'#fffdf8',roughness:.4}));sphere(g,x,1.775,.278,.043,.071,.025,new THREE.MeshStandardMaterial({color:cap?'#547cba':'#7a695d',roughness:.35}));sphere(g,x,1.77,.298,.019,.042,.012,mats.black);sphere(g,x-.012,1.81,.308,.013,.017,.01,mats.white);}
 // eyebrows, delicate nose, smile
 for(let x of [-.115,.115]){let brow=box(g,x,1.91,.261,.09,.017,.022,hair,false);brow.rotation.z=x<0?.08:-.08}
 sphere(g,0,1.69,.285,.022,.03,.025,skin);let smile=new THREE.Mesh(new THREE.TorusGeometry(.045,.008,6,16,Math.PI),new THREE.MeshStandardMaterial({color:'#9e5863'}));smile.position.set(0,1.64,.286);smile.rotation.z=Math.PI;g.add(smile);
 if(cap){sphere(g,0,2.08,-.02,.32,.13,.3,glove);let brim=box(g,0,2.035,.25,.49,.045,.24,glove);brim.rotation.x=-.1;for(let x of [-.23,.23]){let ear=new THREE.Mesh(new THREE.ConeGeometry(.12,.28,4),glove);ear.position.set(x,2.25,-.02);ear.rotation.z=x<0?.25:-.25;ear.castShadow=true;g.add(ear)}}
}
function makeGirl(){girl.clear();const top=new THREE.MeshStandardMaterial({color:'#bb4058',roughness:.84}),skirt=new THREE.MeshStandardMaterial({color:'#344f9b',roughness:.84});
 // torso open-shoulder sweater, arms and hands
 cyl(girl,0,1.09,0,.24,.3,.56,top);sphere(girl,0,1.37,0,.22,.09,.17,skinGirl);box(girl,0,1.31,.015,.44,.09,.35,top); // neckline edge
 for(let s of [-1,1]){limb(girl,[s*.22,1.3,0],[s*.36,.91,.02],.085,.06,top);limb(girl,[s*.36,.91,.02],[s*.38,.68,.08],.06,.05,glove);sphere(girl,s*.38,.65,.1,.075,.09,.075,glove)}
 // pleated skirt
 let sk=new THREE.Mesh(new THREE.CylinderGeometry(.27,.44,.38,12,1,true),skirt);sk.position.y=.79;sk.castShadow=true;girl.add(sk);cyl(girl,0,.98,0,.28,.28,.07,skirt);
 for(let i=0;i<12;i++){let a=i*Math.PI/6;let pleat=box(girl,Math.sin(a)*.35,.78,Math.cos(a)*.35,.018,.33,.025,new THREE.MeshStandardMaterial({color:'#6d79bc'}),false);pleat.rotation.y=a}
 // legs and striped knee socks, shoes
 for(let s of [-1,1]){let x=s*.14;limb(girl,[x,.61,0],[x,.18,.01],.085,.065,skinGirl);cyl(girl,x,.32,.015,.09,.086,.36,sock,16);for(let y of [.42,.48])cyl(girl,x,y,.015,.094,.094,.035,mats.white,16);sphere(girl,x,.09,.08,.105,.07,.18,mats.blue)}
 makeHead(girl,skinGirl,hairGirl,true);
}
function makeBoy(){boy.clear();const hoodieMat=hoodie;
 // joggers and roomy hoodie torso
 for(let s of [-1,1]){let x=s*.13;limb(boy,[x,.85,0],[x,.14,.01],.105,.075,pants);sphere(boy,x,.1,.08,.12,.08,.2,shoe)}
 let torso=box(boy,0,1.12,-.005,.63,.69,.38,hoodieMat);torso.geometry=new THREE.BoxGeometry(.61,.67,.39);sphere(boy,0,1.43,-.04,.2,.16,.2,hoodieMat); // hood behind neck
 for(let s of [-1,1]){limb(boy,[s*.28,1.34,0],[s*.39,.9,.03],.12,.09,hoodieMat);limb(boy,[s*.39,.9,.03],[s*.39,.68,.1],.085,.07,hoodieMat);sphere(boy,s*.39,.64,.12,.09,.09,.08,skinGirl)}
 // hoodie pocket and drawstrings
 box(boy,0,.98,.2,.35,.17,.025,new THREE.MeshStandardMaterial({color:'#888b96'}));for(let x of [-.045,.045])limb(boy,[x,1.37,.2],[x,1.1,.2],.009,.009,mats.white);
 // head, tousled brown hair
 sphere(boy,0,1.77,0,.295,.35,.27,skinGirl);sphere(boy,0,1.92,-.04,.31,.28,.28,new THREE.MeshStandardMaterial({color:'#49352d'}));for(let i=0;i<6;i++){let x=-.24+i*.095;let tuft=new THREE.Mesh(new THREE.ConeGeometry(.1,.27,5),new THREE.MeshStandardMaterial({color:i%2?'#553c32':'#49352d'}));tuft.position.set(x,2.05,.14);tuft.rotation.z=(i-2.5)*-.16;tuft.castShadow=true;boy.add(tuft)}
 for(let x of [-.115,.115]){sphere(boy,x,1.78,.245,.067,.085,.033,mats.white);sphere(boy,x,1.77,.275,.035,.06,.022,new THREE.MeshStandardMaterial({color:'#51677a'}));sphere(boy,x,1.765,.295,.016,.036,.012,mats.black);let brow=box(boy,x,1.91,.26,.09,.014,.02,new THREE.MeshStandardMaterial({color:'#49352d'}),false);}
 sphere(boy,0,1.68,.28,.02,.025,.02,skinGirl);let mouth=new THREE.Mesh(new THREE.TorusGeometry(.04,.007,6,16,Math.PI),new THREE.MeshStandardMaterial({color:'#875d5f'}));mouth.position.set(0,1.63,.285);mouth.rotation.z=Math.PI;boy.add(mouth);
}
makeGirl();makeBoy();
function setGender(g){state.gender=g;girl.visible=g==='girl';boy.visible=g==='boy';$('#compName').textContent=g==='girl'?'МИРА':'ЛЕВ';$('#speaker').textContent=(g==='girl'?'МИРА':'ЛЕВ')+' · рядом';$('#sidecopy').textContent=g==='girl'?'Кажется, она ждёт, когда ты заговоришь.':'Он прислушивается к тишине, будто там есть ответ.';$('#line').textContent=g==='girl'?'Я Мира. Рада, что ты здесь. Тут даже тишина какая-то домашняя. Как ты?':'Лев. Хорошее место, чтобы выдохнуть. Не обязательно сразу что-то объяснять.';localStorage.setItem('quiet-companion-gender',g);$('#modal').classList.remove('open')}
const state={gender:localStorage.getItem('quiet-companion-gender')||'girl',mood:'нежность',affection:32,lastTalk:Date.now(),lastWalk:Date.now(),playerName:localStorage.getItem('quiet-player-name')||'',memories:JSON.parse(localStorage.getItem('quiet-memories')||'[]'),action:'idle',actionUntil:0,walk:false};setGender(state.gender);
// First-person hands: visible foreground, animate subtly and when interacting.
const hands=new THREE.Group();camera.add(hands);scene.add(camera);const handMat=new THREE.MeshStandardMaterial({color:'#f2cabb',roughness:.68});const sleeveMat=new THREE.MeshStandardMaterial({color:'#4c5481',roughness:.8});for(let s of [-1,1]){let arm=box(hands,s*.34,-.39,-.74,.19,.56,.2,sleeveMat);arm.rotation.z=s*.16; sphere(hands,s*.34,-.66,-.67,.105,.12,.11,handMat)}hands.position.set(0,0,0);

// Simple, readable interaction targets on the room props.
const targets=[];function target(name,pos,size){const m=new THREE.Mesh(new THREE.SphereGeometry(1,10,8),new THREE.MeshBasicMaterial({transparent:true,opacity:0,depthWrite:false}));m.position.set(...pos);m.scale.set(...size);m.userData.label=name;scene.add(m);targets.push(m);return m}target('чайник',[-4.58,1.42,.72],[.48,.5,.5]);target('гитара',[-4.4,1.35,-1.6],[.6,1.5,.4]);target('книги',[5.12,1.5,-4.48],[.7,1.3,.4]);target('проектор звёзд',[1.1,.55,1.15],[.4,.4,.4]);target('компьютер',[3.55,1.12,-2.4],[1.2,.8,.25]);
const ray=new THREE.Raycaster(),center=new THREE.Vector2(0,0),keys={},mobileMove={forward:false,back:false,left:false,right:false};let yaw=0,pitch=0,nearThing=null;const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function setMood(m){state.mood=m;$('#mood').textContent=m;$('#sidecopy').textContent=state.gender==='girl'?({нежность:'Она улыбается тебе так, будто приберегла эту улыбку.',радость:'Её глаза светлеют — кажется, вечер стал лучше.',задумчивость:'Она задумчиво теребит край рукава.',смущение:'Она чуть отводит взгляд, но улыбается.',ревность:'В голосе появляется игривая нотка собственницы.',грусть:'Она слушает внимательно и не торопит с ответом.'}[m]||'Она рядом и внимательно тебя слушает.') : ({нежность:'Лев рядом, спокойный и внимательный.',радость:'Уголок его губ выдаёт улыбку.',задумчивость:'Он задумался, глядя на узор света.',грусть:'Он молчит рядом — без неловких советов.'}[m]||'Он внимательно тебя слушает.')}
function show(text,who){$('#speaker').textContent=(who||(state.gender==='girl'?'МИРА':'ЛЕВ'))+' · рядом';$('#line').textContent=text;state.lastTalk=Date.now();sayText(text)}
function sayText(text){if(!('speechSynthesis'in window))return;window.speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(text);u.lang='ru-RU';u.rate=state.gender==='girl'?1.02:.94;u.pitch=state.gender==='girl'?1.08:.88;window.speechSynthesis.speak(u)}
function remember(text){let n=text.match(/(?:меня зовут|зови меня|я —|я -)\s*([А-ЯЁA-Z][а-яёa-z-]{1,20})/i);if(n){state.playerName=n[1];localStorage.setItem('quiet-player-name',state.playerName)}state.memories.push(text.slice(0,150));state.memories=state.memories.slice(-12);localStorage.setItem('quiet-memories',JSON.stringify(state.memories))}
const girlStories=[
'Когда-то я думала, что мечта должна быть огромной и громкой. А потом поняла: иногда мечта — это просто люди, которым можно написать поздно вечером и не притворяться бодрой.',
'У меня была подруга, которая всегда заказывала чай без сахара, а потом брала у меня половину печенья. Я ворчала для вида. До сих пор скучаю по таким маленьким ритуалам.',
'Мне хочется однажды увидеть море зимой. Не ради красивой фотографии — интересно, какое оно, когда вокруг почти никого и можно наконец услышать собственные мысли.',
'Я раньше принимала заботу за обязанность всё исправить. Теперь учусь просто быть рядом. Иногда это намного смелее, чем дать совет.',
'Знаешь, комплимент мне нравится не за идеальность. Мне приятно, когда замечают что-то настоящее — например, что я стараюсь сделать людям уютно.'
],boyStories=[
'Я долго думал, что цель обязана выглядеть впечатляюще со стороны. Потом понял: важнее, чтобы утром ты мог сказать себе «это мой выбор». Довольно неудобное открытие, зато честное.',
'Однажды я провалил важный для себя проект. Самое неожиданное — мир не закончился, а друзья не стали уважать меня меньше. С тех пор ошибки кажутся мне менее убедительными угрозами.',
'Я боюсь не столько неизвестности, сколько привычки однажды перестать задавать вопросы. Поэтому иногда нарочно выбираю дорогу, где не знаю, что за поворотом.',
'Мне нравится мысль, что надёжность — это не обещать никогда не ошибаться. Это отвечать за то, что сделал, и не исчезать, когда разговор стал трудным.',
'Есть одна цель, о которой я редко рассказываю: однажды сделать что-то полезное, что переживёт моё имя. Немного пафосно, да. Но у меня есть право на одну такую мысль.'
];
function reply(input){let t=input.toLowerCase(),name=state.playerName?state.playerName+', ':'';state.affection=clamp(state.affection+2,0,100);$('#affectionBar').style.width=state.affection+'%';
 if(/(привет|здравств|хай|hello)/.test(t))return [name+(state.gender==='girl'?'Привет! Я уже приготовила уютный вечер.':'Привет. Хорошо, что ты заглянул. Как сам?'),state.gender==='girl'?'радость':'нежность'];
 if(/(груст|тяжело|плохо|устал|одинок|тревож|страшно)/.test(t))return [state.gender==='girl'?'Ох, мне жаль. Не нужно сейчас собираться с силами ради меня. Хочешь рассказать, что давит, или просто посидим рядом?':'Понял. Не буду чинить тебя непрошеными советами. Хочешь рассказать подробнее или переключиться на что-нибудь спокойное?', 'грусть'];
 if(/(нравишься|красивая|милая|комплимент|люблю тебя)/.test(t))return [state.gender==='girl'?'Ты умеешь смутить девушку даже через разговор. Спасибо — мне правда приятно, что ты замечаешь меня. А что тебе больше всего нравится в нашем вечере?':'Спасибо. Комплименты я принимаю без споров — редкий полезный навык. И мне нравится, что ты говоришь прямо.',state.gender==='girl'?'смущение':'радость'];
 if(/(ревну|другую|другой девуш|другого парн)/.test(t))return [state.gender==='girl'?'Хм, я не буду устраивать сцен. Но право на маленькое «эй, я тоже тут» за мной оставишь? Ладно, признаюсь — мне важно твоё внимание.':'Я не из тех, кто считает людей собственностью. Но если тебе хочется поговорить о ревности — давай честно, без игр.',state.gender==='girl'?'ревность':'задумчивость'];
 if(/(мечт|чувств|отнош|друж|истор|расскаж)/.test(t))return [(state.gender==='girl'?girlStories:boyStories)[Math.floor(Math.random()*(state.gender==='girl'?girlStories:boyStories).length)],'задумчивость'];
 if(/(спасибо|благодар)/.test(t))return [state.gender==='girl'?'Всегда пожалуйста. Мне хорошо, когда тебе здесь спокойно.':'Не за что. Иногда полезно просто разделить тишину.', 'нежность'];
 if(/(как ты|как дела|настроени)/.test(t))return [state.gender==='girl'?'Я в хорошем настроении — особенно теперь, когда ты здесь. И чуть-чуть любопытствую: что ты обычно делаешь, когда хочешь выдохнуть?':'Нормально. День был из тех, где полезно выключить внутреннего комментатора. А у тебя как?',state.gender==='girl'?'радость':'задумчивость'];
 if(/(люблю|отношен|партнёр|партнер|поцел)/.test(t))return [state.gender==='girl'?'Мне кажется, близость начинается с ощущения, что рядом можно быть несовершенным. Красивые жесты важны, но уважение и внимание — ещё важнее. А ты как думаешь?':'Доверие для меня — не отсутствие сомнений, а решение не прятать их за сарказмом. Непросто, зато отношениям есть на чём стоять.','задумчивость'];
 if(/(меня зовут|зови меня)/.test(t))return ['Очень приятно, '+(state.playerName||'теперь я буду знать, как к тебе обращаться')+'. Постараюсь запомнить. А что тебе обычно помогает почувствовать себя как дома?','радость'];
 if(state.memories.length&&Math.random()<.35)return [state.gender==='girl'?'Ты раньше упоминал кое-что важное — я запомнила. Хочешь вернуться к той теме или сегодня поговорим о чём-то другом?':'Кажется, ты уже делился со мной похожей мыслью. Я не хочу делать вид, что знаю ответ, но готов послушать дальше.','задумчивость'];
 return [state.gender==='girl'?name+'Мне нравится, как ты это формулируешь. Расскажешь чуть подробнее? Я правда хочу понять, что для тебя в этом самое важное.':name+'Любопытно. А ты сам к какому выводу склоняешься? Я обещаю не выдавать сухую шутку за мудрость.','нежность'];
}
function talk(input){input=input.trim();if(!input)return;remember(input);const [answer,mood]=reply(input);setMood(mood);show(answer);state.lastTalk=Date.now()}
$('#send').onclick=()=>{let input=$('#message').value;$('#message').value='';talk(input)};$('#message').addEventListener('keydown',e=>{if(e.key==='Enter')$('#send').click()});
$('#voiceBtn').onclick=()=>{const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){show('В этом браузере нет распознавания речи. Можно написать мне сообщение — я всё равно слушаю внимательно.');return}const rec=new SR();rec.lang='ru-RU';rec.interimResults=false;$('#voiceBtn').textContent='◉';rec.onresult=e=>{$('#message').value=e.results[0][0].transcript;$('#send').click()};rec.onerror=()=>$('#voiceBtn').textContent='🎙';rec.onend=()=>$('#voiceBtn').textContent='🎙';rec.start()};
function action(a){state.action=a;state.actionUntil=performance.now()+5000;state.lastTalk=Date.now();document.querySelectorAll('.tool').forEach(b=>b.classList.toggle('active',b.dataset.action===a));let girl=state.gender==='girl';const lines={
 'обнять':girl?'Иди сюда… Вот так. Иногда объятие лучше целого списка советов.':'Обнимаю. Без лишних слов — иногда так надёжнее.',
 'история':(girl?girlStories:boyStories)[Math.floor(Math.random()*(girl?girlStories:boyStories).length],
 'чай':girl?'Сейчас заварю. Тебе покрепче или помягче? Я пока поставлю чайник и выберу печенье.':'Чай — разумный план. На удивление, почти все хорошие разговоры выдерживают паузу, пока он заваривается.',
 'танцевать':girl?'Только если ты не будешь смеяться над моими поворотами. Хотя… ладно, можешь смеяться, если будешь танцевать тоже.':'Я предупреждал: чувство ритма у меня философское. Но один танец переживём.',
 'петь':girl?'♪ Тихо напеваю знакомую мелодию. Придётся представить, что у меня идеальный слух.':'♪ М-м… Это была либо песня, либо настройка инструмента. Пусть останется загадкой.',
 'играть':girl?'Давай в «два факта и одна мечта»? Я начну: люблю ночные прогулки, боюсь ос и мечтаю увидеть море зимой.':'Сыграем в ассоциации? Я называю слово, ты — первое, что пришло в голову. Слово: «дом».',
 'сесть':girl?'Присяду рядом. Рассказывай, я никуда не спешу.':'Сяду. На удивление удобный способ вести серьёзные разговоры.',
 'лечь':girl?'Полежу немного и буду слушать. Только не включай скучную лекцию о налогах, ладно?':'Лягу. Горизонтальное положение иногда помогает мыслям не строить из себя начальство.',
 'рисовать':girl?'Нарисую маленькую звезду — пусть будет символом этого вечера.':'Набросаю что-нибудь. Гарантирую, что оно будет узнаваемым с очень доброй стороны.',
 'сменить одежду':girl?'Сегодня настроение другое — пусть будет уютный синий кардиган поверх свитера.':'Сменил образ на домашний: теперь я официально выгляжу ещё менее готовым к приключениям.',
 'обнять предмет':'Этот предмет хранит здесь свою маленькую историю.'};let line=lines[a]||'Конечно. Давай сделаем это вместе.';if(a==='чай')state.action='tea';if(a==='танцевать')state.action='dance';if(a==='обнять')state.action='hug';if(a==='сесть')state.action='sit';if(a==='лечь')state.action='lie';if(a==='петь')state.action='sing';if(a==='сменить одежду')state.action='outfit';show(line);setMood(a==='обнять'?'нежность':a==='история'?'задумчивость':a==='танцевать'?'радость':'нежность');}
