function interact(){if(nearThing){let label=nearThing.userData.label;show(objectLines[label]||'Хороший выбор. Расскажешь, что тебе в этом нравится?');if(label==='чайник')action('чай');else if(label==='гитара')action('петь');else if(label==='проектор звёзд')setMood('задумчивость');return}
 const dist=avatar.position.distanceTo(camera.position);if(dist<4.4){action('обнять');return}show('Подойди немного ближе, если хочется поговорить.');}
function refreshTarget(){ray.setFromCamera(center,camera);const hit=ray.intersectObjects(targets,false)[0];nearThing=hit&&hit.distance<5.5?hit.object:null;let dist=avatar.position.distanceTo(camera.position);const showIt=!!nearThing||dist<4.4;$('#interact').classList.toggle('show',showIt);$('#interact').textContent=nearThing?'E · '+nearThing.userData.label:dist<4.4?'E · обнять / поговорить':'E · подойти к спутнику'}
window.addEventListener('keydown',e=>{keys[e.code]=true;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();if(e.code==='KeyE')interact();if(e.code==='Escape')document.exitPointerLock?.()});window.addEventListener('keyup',e=>keys[e.code]=false);
renderer.domElement.addEventListener('click',()=>{if(innerWidth>700&&!document.pointerLockElement)renderer.domElement.requestPointerLock?.()});document.addEventListener('mousemove',e=>{if(document.pointerLockElement===renderer.domElement){yaw-=e.movementX*.0022;pitch=clamp(pitch-e.movementY*.0018,-.72,.62)}});
let drag=null;renderer.domElement.addEventListener('pointerdown',e=>{if(innerWidth<=700){drag=[e.clientX,e.clientY];renderer.domElement.setPointerCapture(e.pointerId)}});renderer.domElement.addEventListener('pointermove',e=>{if(drag){yaw-=(e.clientX-drag[0])*.004;pitch=clamp(pitch-(e.clientY-drag[1])*.003,-.68,.56);drag=[e.clientX,e.clientY]}});renderer.domElement.addEventListener('pointerup',()=>drag=null);
